{"content": "from flask import Flask, jsonify, request, send_from_directory
import json
import os

app = Flask(__name__, static_folder='../frontend')

# --- Mock Data ---
RESTAURANTS = [
    {"id": 1, "name": "The Italian Place", "cuisine": "Italian", "rating": 4.5, "address": "123 Pasta Ln"},
    {"id": 2, "name": "Sushi Heaven", "cuisine": "Japanese", "rating": 4.8, "address": "456 Fish St"},
    {"id": 3, "name": "Burger Joint", "cuisine": "American", "rating": 4.2, "address": "789 Patty Ave"},
    {"id": 4, "name": "Spicy Tacos", "cuisine": "Mexican", "rating": 4.6, "address": "101 Chili Rd"},
]

# Simple in-memory store for favorites (ID -> True)
FAVORITES = {}

# --- API Endpoints ---

@app.route('/api/restaurants', methods=['GET'])
def list_restaurants():
    """Search restaurants based on query parameters."""
    query = request.args.get('q', '').lower()
    cuisine = request.args.get('cuisine', '').lower()

    results = RESTAURANTS

    if query:
        results = [r for r in results if query in r['name'].lower() or query in r['address'].lower()]

    if cuisine:
        results = [r for r in results if cuisine in r['cuisine'].lower()]

    # Add favorite status to each restaurant
    for restaurant in results:
        restaurant['is_favorite'] = restaurant['id'] in FAVORITES

    return jsonify(results)

@app.route('/api/favorite/<int:restaurant_id>', methods=['POST'])
def toggle_favorite(restaurant_id):
    """Toggle a restaurant as a favorite."""
    if not any(r['id'] == restaurant_id for r in RESTAURANTS):
        return jsonify({"error": "Restaurant not found"}), 404

    if restaurant_id in FAVORITES:
        del FAVORITES[restaurant_id]
        is_favorite = False
    else:
        FAVORITES[restaurant_id] = True
        is_favorite = True

    return jsonify({"id": restaurant_id, "is_favorite": is_favorite})

@app.route('/api/favorites', methods=['GET'])
def get_favorites():
    """Get the list of favorited restaurants."""
    favorite_restaurants = [r for r in RESTAURANTS if r['id'] in FAVORITES]
    return jsonify(favorite_restaurants)

# --- Serve Frontend ---
@app.route('/', defaults={'path': ''})
@app.route('/<path:path>')
def serve(path):
    """Serve the frontend files."""
    if path != "" and os.path.exists(os.path.join(app.static_folder, path)):
        return send_from_directory(app.static_folder, path)
    else:
        # Serve index.html for all other routes to allow client-side routing
        return send_from_directory(app.static_folder, 'index.html')

if __name__ == '__main__':
    # Run on all interfaces for potential external access during development
    app.run(debug=True, host='0.0.0.0', port=5000)", "path": "FoodSearchMVP_Web_New_Simple/backend/app.py"}

